package com.nexodb.ui;

import com.nexodb.db.*;import com.nexodb.util.*;import javax.swing.*;import javax.swing.border.EmptyBorder;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import static com.nexodb.util.I18n.tr;

/** Read-only lineage browser and Mermaid/Markdown documentation exporter. */
final class DataLineagePanel extends JPanel {
 private final JdbcSession origin;private final String database;private final DefaultTableModel model=new DefaultTableModel(new Object[]{tr("Origen"),tr("Destino"),tr("Tipo"),tr("Detalle")},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable table=new JTable(model);private final JTextArea mermaid=new JTextArea();private final JLabel status=new JLabel(" ");private final JButton refresh=UiLanguage.button("Actualizar"),export=UiLanguage.button("Exportar documentación…"),cancel=UiLanguage.button("Cancelar");private SwingWorker<DataLineageService.Graph,Void> worker;private volatile JdbcSession.ReadLease lease;private DataLineageService.Graph graph;private boolean disposed;
 DataLineagePanel(JdbcSession origin,String database){super(new BorderLayout(6,6));this.origin=origin;this.database=database;setBorder(new EmptyBorder(8,8,8,8));JToolBar bar=new JToolBar();bar.setFloatable(false);bar.add(refresh);bar.add(cancel);bar.add(export);add(bar,BorderLayout.NORTH);table.setAutoCreateRowSorter(true);table.setFillsViewportHeight(true);mermaid.setEditable(false);mermaid.setFont(new Font(Font.MONOSPACED,Font.PLAIN,13));JTabbedPane tabs=new JTabbedPane();tabs.addTab(tr("Dependencias"),new JScrollPane(table));tabs.addTab("Mermaid",new JScrollPane(mermaid));add(tabs);add(status,BorderLayout.SOUTH);refresh.addActionListener(e->load());cancel.addActionListener(e->cancel());export.addActionListener(e->save());load();}
 JdbcSession origin(){return origin;}String database(){return database;}void disposePanel(){disposed=true;cancel();}
 private void load(){if(disposed||worker!=null&&!worker.isDone())return;refresh.setEnabled(false);export.setEnabled(false);cancel.setEnabled(true);status.setText(tr("Leyendo relaciones y dependencias…"));worker=new SwingWorker<>(){protected DataLineageService.Graph doInBackground()throws Exception{try(JdbcSession.ReadLease read=origin.borrowReadOnly(10_000)){lease=read;return DataLineageService.from(DataDictionaryService.complete(read.session(),database,null));}finally{lease=null;}}protected void done(){try{if(isCancelled())return;graph=get();render();status.setText(graph.nodes().size()+tr(" objetos · ")+graph.edges().size()+tr(" dependencias"));}catch(Exception error){status.setText(tr("No se pudo construir el linaje: ")+message(error));}finally{worker=null;refresh.setEnabled(!disposed);cancel.setEnabled(false);export.setEnabled(graph!=null);}}};worker.execute();}
 private void render(){model.setRowCount(0);for(var edge:graph.edges())model.addRow(new Object[]{edge.source(),edge.target(),edge.kind(),edge.detail()});mermaid.setText(DataLineageService.mermaid(graph));mermaid.setCaretPosition(0);}
 private void save(){JFileChooser chooser=new JFileChooser();chooser.setSelectedFile(new java.io.File("linaje-"+database+".md"));if(chooser.showSaveDialog(this)!=JFileChooser.APPROVE_OPTION)return;try{Path target=chooser.getSelectedFile().toPath().toAbsolutePath();if(target.getParent()!=null)Files.createDirectories(target.getParent());Files.writeString(target,DataLineageService.markdown(graph),StandardCharsets.UTF_8);status.setText(tr("Documentación exportada: ")+target.getFileName());}catch(Exception error){JOptionPane.showMessageDialog(this,message(error),tr("Linaje"),JOptionPane.ERROR_MESSAGE);}}
 private void cancel(){if(worker!=null)worker.cancel(true);if(lease!=null)try{lease.session().cancel();}catch(Exception ignored){}}private static String message(Throwable error){while(error.getCause()!=null)error=error.getCause();return java.util.Objects.toString(error.getMessage(),error.getClass().getSimpleName());}
}
